def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a, b in history if a == 'C')
    my_d = n - my_c
    my_prev, opp_prev = history[-1]

    if n < 4:
        return 'C'

    # Endgame: exploit known cooperators, punish defectors
    if n >= 96:
        if opp_d <= 2:
            return 'D'
        if opp_prev == 'D':
            return 'D'
        if opp_d * 2 >= n:
            return 'D'
        if n >= 99:
            return 'D'
        return 'C'

    # Detect sustained defection -> always defect
    if opp_d >= n - 1 and n >= 6:
        return 'D'

    # Detect pure cooperator -> exploit steadily but not too early/late
    if opp_d == 0:
        if n >= 30:
            return 'D'
        return 'C'

    # High defection rate: defect hard
    if opp_d * 5 >= n * 3:
        if n % 9 == 0:
            return 'C'
        return 'D'

    # Recovery from bad starts: if opponent defected a lot early but has
    # recently cooperated, forgive quickly to restore mutual cooperation.
    if n >= 6:
        last4 = history[-4:]
        last4_opp_c = sum(1 for a, b in last4 if b == 'C')
        if opp_d >= 4 and last4_opp_c >= 3:
            return 'C'

    # Opponent just cooperated
    if opp_prev == 'C':
        # If we defected last round and they cooperated, stop exploiting
        # unless they are very forgiving/passive.
        if my_prev == 'D':
            if opp_d <= 2 and n < 90:
                return 'D'
            return 'C'
        # Mostly cooperate, occasional probe
        if n >= 20 and opp_d <= 3:
            if n % 13 == 0:
                return 'D'
        return 'C'

    # Opponent just defected
    # Very forgiving retaliation: check recent opponent pattern
    if n >= 5:
        last5 = history[-5:]
        last5_opp_c = sum(1 for a, b in last5 if b == 'C')
        if last5_opp_c >= 4:
            # Isolated defection against mostly-cooperative opponent
            return 'D'
        if last5_opp_c >= 3:
            return 'D'
    # Occasional forgiveness to break DD spirals
    if opp_d <= max(2, n // 12):
        return 'C'
    if n % 7 == 0:
        return 'C'
    return 'D'
